function seek(time){if(!frames.length)return;playTime=clamp(time,0,totalTime());const sample=sampleAnimation(playTime);previewState=sample.state;previewCamera=sample.camera;render();updateClock();properties()}
function stopPlayback(clear=true){playing=false;if(rafId!==null){cancelAnimationFrame(rafId);rafId=null}if(clear){previewState=null;previewCamera=null}updateClock()}
function play(){if(playing||!frames.length)return;flushFrame();if(playTime>=totalTime())playTime=0;playing=true;playStamp=performance.now();closeMenu();const tick=stamp=>{if(!playing)return;playTime+=(stamp-playStamp)/1000;playStamp=stamp;const total=totalTime();if(playTime>=total){if(loopAnimation&&total>0)playTime%=total;else{seek(total);stopPlayback(false);return}}seek(playTime);rafId=requestAnimationFrame(tick)};rafId=requestAnimationFrame(tick);updateClock()}
$('#play').onclick=play;$('#pause').onclick=()=>stopPlayback(false);$('#rewind').onclick=()=>{stopPlayback(true);seek(0)};$('#scrubber').oninput=e=>{stopPlayback(false);seek(Number(e.target.value))};$('#edit-frame').onclick=()=>{stopPlayback(true);render();properties();renderTimeline()};
function updateClock(){const duration=totalTime();$('#scrubber').max=Math.max(.01,duration);$('#scrubber').value=playTime;$('#time-label').textContent=`${playTime.toFixed(1)} / ${duration.toFixed(1)} s`;$('#play').disabled=playing||!frames.length;$('#pause').disabled=!playing;const seg=previewState?playSegment(playTime):null;document.querySelectorAll('[data-frame-index]').forEach(b=>b.classList.toggle('playing-frame',!!seg&&Number(b.dataset.frameIndex)===seg.i))}
function thumbnail(frame){const svg=tag('svg',{xmlns:'http://www.w3.org/2000/svg',viewBox:orientation==='vertical'?'0 0 760 1130':'0 0 1130 760'});svg.append(board.querySelector('defs').cloneNode(true));tag('rect',{width:1130,height:1130,fill:'white'},svg);const g=tag('g',{transform:sceneTransform(boardRotation)},svg);if(background==='pitch'){appendGrassSvg(g,pitchColor,grassPattern,orientation==='vertical'?{x:0,y:0,w:760,h:1130}:{x:0,y:0,w:1130,h:760},boardRotation);appendHalfspacesSvg(g,halfspaces,pitchColor);const pitch=$('#pitch').cloneNode(true);pitch.removeAttribute('id');pitch.removeAttribute('display');g.append(pitch);appendPitchGoalsSvg(g,pitchColor)}const old=previewState;previewState=frame.state;for(const o of orderedObjects(frame.state))draw(o,g);previewState=old;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg))}
function renderTimeline(){const panel=$('#timeline');panel.replaceChildren();frames.forEach((frame,i)=>{const b=document.createElement('button');b.className='frame-card'+(i===activeFrame?' active-frame':'');b.dataset.frameIndex=i;const img=document.createElement('img');img.alt=`Klatka ${i+1}`;img.src=thumbnail(frame);const caption=document.createElement('span');caption.textContent=`${i+1} · ${frame.hold.toFixed(1)} s + ${i<frames.length-1?frame.duration.toFixed(1):'0.0'} s`;b.append(img,caption);b.onclick=()=>selectFrame(i);panel.append(b)});$('#first-frame').hidden=!!frames.length;for(const id of ['duplicate-frame','remove-frame','frame-hold','frame-duration','frame-before','frame-after'])$('#'+id).disabled=!frames.length;$('#frame-before').disabled=!frames.length||activeFrame===0;$('#frame-after').disabled=!frames.length||activeFrame===frames.length-1;$('#frame-duration').disabled=!frames.length||activeFrame===frames.length-1;$('#frame-hold').value=frames[activeFrame]?.hold??.5;$('#frame-duration').value=frames[activeFrame]?.duration??1.5;$('#frame-cameras').checked=frameCameras;$('#loop').checked=loopAnimation;updateClock();fitBoard()}
