 ui.form.onsubmit=e=>{e.preventDefault();const tagNames=tags.names();if(!libraryPrepareMutation([p.id])){ui.error.textContent='Nie zapisano bieżącej pracy. Eksportuj kopię JSON.';return}if(libraryTransaction(()=>{const item=projects.find(x=>x.id===p.id);item.name=cleanLibraryName(name.value).slice(0,120);item.meta={...item.meta,description:desc.value.slice(0,500),folderId:folder.value||null,tagIds:[...new Set(tagNames.map(n=>libraryEnsureTag(n).id))],favorite:favorite.checked,thumbnailFrameId:thumbnail.value||null};item.updatedAt=new Date().toISOString()})){ui.dialog.close('saved');notice('Zapisano organizację projektu.');refresh()}else ui.error.textContent='Nie zapisano zmian. Sprawdź komunikat biblioteki.'};
