 const prefsKey='linia-library-preferences-v1';let prefs={layout:'grid',sort:'updated',direction:'desc'};try{const p=JSON.parse(localStorage.getItem(prefsKey));if(p){if(['grid','list'].includes(p.layout))prefs.layout=p.layout;if(['name','updated','opened'].includes(p.sort))prefs.sort=p.sort;if(['asc','desc'].includes(p.direction))prefs.direction=p.direction}}catch(e){}
 let q={view:'all',search:'',folderId:'',tagIds:[],tagMode:'all',animation:false,...prefs},page=0,chosen=new Set(),inputTimer,allResults=[];const perPage=24;
